CREATE TABLE IF NOT EXISTS schema_migrations(version BIGINT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS certificate_authorities(id TEXT PRIMARY KEY,name TEXT NOT NULL,type TEXT NOT NULL,parent_id TEXT,tenant_key TEXT NOT NULL,region TEXT NOT NULL,algorithm TEXT NOT NULL,key_reference TEXT NOT NULL,status TEXT NOT NULL,certificate_pem TEXT,not_before TIMESTAMPTZ NOT NULL,not_after TIMESTAMPTZ NOT NULL,version BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS certificate_profiles(id TEXT PRIMARY KEY,ca_id TEXT NOT NULL REFERENCES certificate_authorities(id),tenant_key TEXT NOT NULL,name TEXT NOT NULL,config JSONB NOT NULL,status TEXT NOT NULL,version BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS certificates(id TEXT PRIMARY KEY,tenant_key TEXT NOT NULL,ca_id TEXT NOT NULL,profile_id TEXT NOT NULL,serial TEXT,fingerprint TEXT UNIQUE,public_key_fingerprint TEXT,csr_pem TEXT NOT NULL,pem TEXT,chain_pem TEXT,status TEXT NOT NULL,validity JSONB NOT NULL,idempotency_key TEXT NOT NULL,revocation_reason TEXT,revoked_at TIMESTAMPTZ,version BIGINT NOT NULL,created_by TEXT,updated_by TEXT,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,UNIQUE(tenant_key,idempotency_key));
CREATE TABLE IF NOT EXISTS audit_records(id TEXT PRIMARY KEY,aggregate_type TEXT NOT NULL,aggregate_id TEXT NOT NULL,tenant_key TEXT NOT NULL,action TEXT NOT NULL,"from" TEXT,"to" TEXT,actor TEXT NOT NULL,detail TEXT,previous_hash TEXT,hash TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS outbox_events(id TEXT PRIMARY KEY,aggregate_id TEXT NOT NULL,type TEXT NOT NULL,payload JSONB NOT NULL,attempts INT NOT NULL DEFAULT 0,available_at TIMESTAMPTZ NOT NULL,delivered_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL);
